-- Cloud integration test: temporary synthetic users, all data rolled back.
begin;
create function pg_temp.must_fail(command text) returns void language plpgsql as $$
begin
 begin execute command; exception when others then return; end;
 raise exception 'FAIL: unauthorized/invalid operation succeeded: %',command;
end $$;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$
begin if value is not true then raise exception 'FAIL: %',label; end if; end $$;
select set_config('rf.test.leader',gen_random_uuid()::text,true),set_config('rf.test.member',gen_random_uuid()::text,true),set_config('rf.test.supervisor',gen_random_uuid()::text,true),set_config('rf.test.outsider',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select current_setting('rf.test.'||n)::uuid,'rf-mvp3-'||current_setting('rf.test.'||n)||'@example.invalid',now(),jsonb_build_object('full_name','MVP3 test '||n) from unnest(array['leader','member','supervisor','outsider']) n;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.w',public.rf_create_workspace('MVP3 test team','Isolated test research','Test Leader')::text,true);
select pg_temp.assert_true((select count(*)=7 from public.rf_channels where workspace_id=current_setting('rf.test.w')::uuid),'seven default channels');
select pg_temp.assert_true((select count(*)=10 from public.rf_document_folders where workspace_id=current_setting('rf.test.w')::uuid),'ten default folders');
insert into public.rf_workspace_invitations(workspace_id,email,role) select current_setting('rf.test.w')::uuid,'rf-mvp3-'||current_setting('rf.test.'||n)||'@example.invalid',n from unnest(array['member','supervisor']) n;
select set_config('rf.test.tokenmember',(select token::text from public.rf_workspace_invitations where workspace_id=current_setting('rf.test.w')::uuid and role='member'),true),set_config('rf.test.tokensupervisor',(select token::text from public.rf_workspace_invitations where workspace_id=current_setting('rf.test.w')::uuid and role='supervisor'),true);
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select public.rf_accept_invitation(current_setting('rf.test.tokenmember')::uuid,'Test Member');
select set_config('request.jwt.claim.sub',current_setting('rf.test.supervisor'),true);
select public.rf_accept_invitation(current_setting('rf.test.tokensupervisor')::uuid,'Test Supervisor');
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);

select set_config('rf.test.paper',(public.rf_operations('paper_save',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'title','Synthetic paper','status','Planning','authors',jsonb_build_array(current_setting('rf.test.member'))))->>'id'),true);
select pg_temp.assert_true((select count(*)=14 from public.rf_paper_sections where paper_id=current_setting('rf.test.paper')::uuid),'fourteen default paper sections');
select set_config('rf.test.section',(select id::text from public.rf_paper_sections where paper_id=current_setting('rf.test.paper')::uuid order by position limit 1),true);
select public.rf_operations('section_save',(select to_jsonb(s)||jsonb_build_object('assignees',jsonb_build_array(current_setting('rf.test.member')),'status','Drafting') from public.rf_paper_sections s where id=current_setting('rf.test.section')::uuid));
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.must_fail(format('select public.rf_operations(''section_feedback'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'section_id',current_setting('rf.test.section'),'kind','Approved','body','Forged approval')));
select public.rf_operations('section_save',(select to_jsonb(s)||jsonb_build_object('status','Supervisor Review','notes','Researcher entered draft') from public.rf_paper_sections s where id=current_setting('rf.test.section')::uuid));
select set_config('request.jwt.claim.sub',current_setting('rf.test.supervisor'),true);
select public.rf_operations('section_feedback',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'section_id',current_setting('rf.test.section'),'kind','Approved','body','Synthetic test approval, not a research finding'));
select pg_temp.assert_true((select status='Approved' from public.rf_paper_sections where id=current_setting('rf.test.section')::uuid),'supervisor approval persisted');
select pg_temp.must_fail(format('update public.rf_paper_feedback set body=''forged'' where section_id=%L',current_setting('rf.test.section')));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.dataset',(public.rf_operations('dataset_save',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'name','Synthetic confidential metadata','classification','Confidential','permission_status','Pending','status','Permission Pending','restricted',true,'readers','[]'::jsonb))->>'id'),true);
select pg_temp.must_fail(format('select public.rf_operations(''dataset_save'',%L::jsonb)',(select to_jsonb(d)||'{"status":"Ready for Analysis","permission_status":"Granted"}'::jsonb from public.rf_datasets d where id=current_setting('rf.test.dataset')::uuid)));
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)=0 from public.rf_datasets where id=current_setting('rf.test.dataset')::uuid),'restricted dataset hidden');
select pg_temp.assert_true((select count(*)=0 from public.rf_dataset_changes where dataset_id=current_setting('rf.test.dataset')::uuid),'restricted metadata history hidden');
select pg_temp.must_fail(format('select public.rf_operations(''dataset_version'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'dataset_id',current_setting('rf.test.dataset'),'kind','Dataset','external_url','https://example.invalid/test','name','Denied')));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select public.rf_operations('dataset_save',(select to_jsonb(d)||jsonb_build_object('permission_status','Granted','status','Collected','readers',jsonb_build_array(current_setting('rf.test.member')),'metadata',jsonb_build_object('permission_evidence','Synthetic fixture consent','usage_scope','Testing only')) from public.rf_datasets d where id=current_setting('rf.test.dataset')::uuid));
select pg_temp.assert_true((select count(*)>=2 from public.rf_dataset_changes where dataset_id=current_setting('rf.test.dataset')::uuid),'private dataset change snapshots persisted');
select pg_temp.must_fail(format('update public.rf_dataset_changes set after_value=''{}''::jsonb where dataset_id=%L',current_setting('rf.test.dataset')));
select set_config('rf.test.path',current_setting('rf.test.w')||'/'||current_setting('rf.test.dataset')||'/'||current_setting('rf.test.leader')||'/'||gen_random_uuid()||'.csv',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-datasets',current_setting('rf.test.path'),'{"mimetype":"text/csv","size":12}');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.version',(public.rf_operations('dataset_version',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'dataset_id',current_setting('rf.test.dataset'),'kind','Dataset','path',current_setting('rf.test.path'),'name','synthetic.csv'))->>'id'),true);
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)=1 from public.rf_dataset_versions where id=current_setting('rf.test.version')::uuid),'explicit dataset reader can see version');
select pg_temp.must_fail(format('select public.rf_operations(''dataset_version'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'dataset_id',current_setting('rf.test.dataset'),'kind','Dataset','external_url','https://example.invalid/forged-version','name','Reader may not append')));
select pg_temp.assert_true(not rf_private.dataset_upload(current_setting('rf.test.w')||'/'||current_setting('rf.test.dataset')||'/'||current_setting('rf.test.member')||'/'||gen_random_uuid()||'.csv'),'read permission alone does not allow raw upload');
select pg_temp.assert_true((select count(*)=0 from storage.objects where name=current_setting('rf.test.path')),'cannot sign private dataset without logged authorization');
select public.rf_operations('dataset_download',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.version')));
select pg_temp.assert_true((select count(*)=1 from public.rf_dataset_access_events where version_id=current_setting('rf.test.version')::uuid),'download issuance logged');
select pg_temp.assert_true((select count(*)=0 from storage.objects where name=current_setting('rf.test.path')),'browser cannot sign directly; authenticated Edge Function enforces expiry');
select pg_temp.must_fail(format('update public.rf_dataset_versions set name=''tamper'' where id=%L',current_setting('rf.test.version')));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
insert into public.rf_tasks(workspace_id,title,assignee_id,due_date) values(current_setting('rf.test.w')::uuid,'MVP3 assigned fixture',current_setting('rf.test.member')::uuid,current_date);
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)>=1 from public.rf_notifications where category='Tasks'),'task assignment notification persisted');
select public.rf_operations('deadline_refresh',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'timezone','Asia/Colombo'));
select public.rf_operations('deadline_refresh',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'timezone','Asia/Colombo'));
select pg_temp.assert_true((select count(*)=1 from public.rf_notifications where category='Deadlines'),'duplicate deadline reconciliation suppressed');
select public.rf_operations('notifications_read',jsonb_build_object('workspace_id',current_setting('rf.test.w')));
select pg_temp.assert_true((select bool_and(read_at is not null) from public.rf_notifications),'personal read state persisted');
select pg_temp.must_fail(format('insert into public.rf_notifications(workspace_id,user_id,category,event_key,message,destination) values(%L,%L,''Tasks'',''forged'',''forged'',''/tasks'')',current_setting('rf.test.w'),current_setting('rf.test.leader')));
select pg_temp.must_fail(format('select rf_private.notify(%L,%L,''Tasks'',''forged'',''/tasks'')',current_setting('rf.test.w'),current_setting('rf.test.leader')));
select public.rf_operations('preference',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'category','Tasks','enabled',false));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
insert into public.rf_tasks(workspace_id,title,assignee_id) values(current_setting('rf.test.w')::uuid,'Preference fixture',current_setting('rf.test.member')::uuid);
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)=1 from public.rf_notifications where category='Tasks'),'disabled preference suppresses new task event');
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.folder',(select id::text from public.rf_document_folders where workspace_id=current_setting('rf.test.w')::uuid limit 1),true);
select set_config('rf.test.doc',(public.rf_collaborate('document_create',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'folder_id',current_setting('rf.test.folder'),'title','Restricted paper fixture','restricted',true))->>'id'),true);
select set_config('rf.test.docpath',current_setting('rf.test.w')||'/'||current_setting('rf.test.leader')||'/'||gen_random_uuid()||'.txt',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-files',current_setting('rf.test.docpath'),'{"mimetype":"text/plain","size":12}');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.docversion',(public.rf_collaborate('file_register',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'document_id',current_setting('rf.test.doc'),'path',current_setting('rf.test.docpath'),'name','draft.txt'))->>'id'),true);
select public.rf_operations('section_save',(select to_jsonb(s)||jsonb_build_object('status','Drafting','version_id',current_setting('rf.test.docversion')) from public.rf_paper_sections s where id=current_setting('rf.test.section')::uuid));
select pg_temp.assert_true((select version_id=current_setting('rf.test.docversion')::uuid from public.rf_paper_sections where id=current_setting('rf.test.section')::uuid),'paper reuses immutable document version');
select pg_temp.assert_true((select status='Drafting' from public.rf_paper_sections where id=current_setting('rf.test.section')::uuid),'draft edit invalidates prior approval');
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.must_fail(format('select public.rf_operations(''section_save'',%L::jsonb)',(select to_jsonb(s)||'{"status":"Drafting"}'::jsonb from public.rf_paper_sections s where id=current_setting('rf.test.section')::uuid)));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.repository',(public.rf_operations('repository_save',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'url','https://github.com/example/research'))->>'id'),true);
select public.rf_operations('github_link',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'repository_id',current_setting('rf.test.repository'),'task_id',(select id from public.rf_tasks where workspace_id=current_setting('rf.test.w')::uuid limit 1),'member_id',current_setting('rf.test.member'),'kind','Issue','url','https://github.com/example/research/issues/7'));
select pg_temp.must_fail(format('select public.rf_operations(''github_link'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'repository_id',current_setting('rf.test.repository'),'task_id',(select id from public.rf_tasks where workspace_id=current_setting('rf.test.w')::uuid limit 1),'member_id',current_setting('rf.test.member'),'kind','Issue','url','https://github.com.evil.invalid/example/research/issues/7')));
select public.rf_operations('dataset_save',(select to_jsonb(d)||jsonb_build_object('readers','[]'::jsonb) from public.rf_datasets d where id=current_setting('rf.test.dataset')::uuid));
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)=0 from storage.objects where name=current_setting('rf.test.path')),'revocation blocks new storage access despite an earlier issuance grant');
select pg_temp.must_fail(format('select public.rf_operations(''dataset_download'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.version'))));
select set_config('request.jwt.claim.sub',current_setting('rf.test.outsider'),true);
select pg_temp.assert_true((select count(*)=0 from public.rf_papers where id=current_setting('rf.test.paper')::uuid),'cross-workspace paper isolation');
select pg_temp.assert_true((select count(*)=0 from public.rf_dataset_versions where id=current_setting('rf.test.version')::uuid),'cross-workspace dataset isolation');
select pg_temp.must_fail(format('select public.rf_operations(''report_event'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'report_type','Dataset Registry Summary')));
select 'PASS: paper defaults, assignments, supervisor decisions, immutable feedback/versions, dataset ACL and logged downloads, evidence gate, notifications/dedup/read/preferences, forged notification prevention, export membership and cross-workspace isolation; all fixtures rolled back' as result;
rollback;
